SELECT node_id as id, node_name as name, node_type as type, description, 3 as level 
FROM ld_knowledge_nodes 
WHERE node_id = #{nodeId}

SELECT node_id as id, node_name as name, node_type as type, description, 2 as level 
FROM ld_knowledge_nodes 
WHERE node_type = #{nodeType} AND parent_id = #{parentId}
ORDER BY node_name

    LIMIT #{limit}

