SELECT node_id as id, node_name as name, node_type as type, description, 2 as level 
FROM ld_knowledge_nodes 
WHERE node_type = 'variety' AND parent_id = #{parentId} AND node_id != #{excludeNodeId}
ORDER BY node_name
LIMIT #{limit}
